import { readFileSync } from 'node:fs';
import { describe, it, expect } from 'vitest';
import { parse } from '../parser/index.js';
import { simulate } from '../simulate.js';
import { BSIM3v3 } from './bsim3v3.js';
import { evaluateDC } from './bsim3v3-dc.js';

// Issue #589: ngspice-47 reference values for identical BSIM3v3.3.0 decks,
// generated by benchmarks/bsim3-dc-589/reference.ts (`ngspice -b`, numdgt=15).
// Operating points print the b3ld.c outputs @m1[id|gm|gds|gmbs|vth] at
// source-forced terminal voltages; sweeps record the terminal current i(vd).
interface ReferencePoint {
  vgs: number; vds: number; vbs: number;
  id: number; gm: number; gds: number; gmbs: number; vth: number; ivd: number;
}
interface ReferenceCase {
  name: string;
  type: 1 | -1;
  operatingPoints: { deck: string; points: ReferencePoint[] };
  sweep: { deck: string; points: { vd: number; ivd: number }[] };
}
const reference = JSON.parse(readFileSync(
  new URL('../../../../benchmarks/bsim3-dc-589/ngspice-47-dc.json', import.meta.url), 'utf8',
)) as { engine: string; cases: ReferenceCase[] };

// Acceptance (#589): within 1% of ngspice-47. Values smaller than the floor are
// compared absolutely (A for currents, S for conductances).
const RELATIVE = 0.01;
const CURRENT_FLOOR = 1e-12;
const CONDUCTANCE_FLOOR = 1e-12;

function relativeError(actual: number, expected: number, floor: number): number {
  return Math.abs(actual - expected) / Math.max(Math.abs(expected), floor);
}

function deviceOf(deck: string): BSIM3v3 {
  const device = parse(deck).compile().devices.find((d): d is BSIM3v3 => d instanceof BSIM3v3);
  if (!device) throw new Error('no BSIM3 device in deck');
  return device;
}

describe('BSIM3v3 DC core matches ngspice-47 b3ld.c (#589)', () => {
  it('uses the ngspice-47 reference', () => {
    expect(reference.engine).toBe('ngspice-47');
    expect(reference.cases.length).toBeGreaterThanOrEqual(13);
  });

  for (const c of reference.cases) {
    it(`${c.name}: Id, gm, gds, gmbs and Vth at ${c.operatingPoints.points.length} biases`, () => {
      const device = deviceOf(c.operatingPoints.deck);
      let worst = { error: 0, label: '' };
      for (const p of c.operatingPoints.points) {
        // b3ld.c BSIM3mode = -1 evaluates (Vgd, -Vds, Vbd); @m1[...] report that orientation.
        const reverse = p.vds < 0;
        const dc = evaluateDC(
          device.model, device.size,
          reverse ? p.vgs - p.vds : p.vgs, Math.abs(p.vds), reverse ? p.vbs - p.vds : p.vbs,
        );
        const m = device.size.m;
        const checks: [string, number, number, number][] = [
          ['id', m * dc.Ids, p.id, CURRENT_FLOOR],
          ['gm', m * dc.gm, p.gm, CONDUCTANCE_FLOOR],
          ['gds', m * dc.gds, p.gds, CONDUCTANCE_FLOOR],
          ['gmbs', m * dc.gmbs, p.gmbs, CONDUCTANCE_FLOOR],
          ['vth', dc.von, p.vth, 1],
        ];
        for (const [label, actual, expected, floor] of checks) {
          const error = relativeError(actual, expected, floor);
          if (!(error <= worst.error)) {
            worst = { error, label: `${label} at Vgs=${p.vgs} Vds=${p.vds} Vbs=${p.vbs}: ${actual} vs ${expected}` };
          }
        }
      }
      expect(worst.error, worst.label).toBeLessThan(RELATIVE);
    });

    it(`${c.name}: terminal i(VD) at every operating point`, async () => {
      let worst = { error: 0, label: '' };
      for (const p of c.operatingPoints.points) {
        const deck = c.operatingPoints.deck
          .replace(/^VD d 0 DC .*$/m, `VD d 0 DC ${c.type * p.vds}`)
          .replace(/^VG g 0 DC .*$/m, `VG g 0 DC ${c.type * p.vgs}`)
          .replace(/^VB b 0 DC .*$/m, `VB b 0 DC ${c.type * p.vbs}`)
          .replace(/^\.end$/m, '.op\n.end');
        const current = (await simulate(deck)).dc!.current('VD');
        const error = relativeError(current, p.ivd, CURRENT_FLOOR);
        if (!(error <= worst.error)) {
          worst = { error, label: `i(VD) at Vgs=${p.vgs} Vds=${p.vds} Vbs=${p.vbs}: ${current} vs ${p.ivd}` };
        }
      }
      expect(worst.error, worst.label).toBeLessThan(RELATIVE);
    });

    it(`${c.name}: terminal i(VD) matches the ngspice Id-Vds sweep`, async () => {
      const result = await simulate(c.sweep.deck);
      const current = result.dcSweep!.current('VD');
      expect(current.length).toBe(c.sweep.points.length);
      let worst = { error: 0, label: '' };
      c.sweep.points.forEach((p, i) => {
        const error = relativeError(current[i], p.ivd, CURRENT_FLOOR);
        if (!(error <= worst.error)) worst = { error, label: `i(VD) at VD=${p.vd}: ${current[i]} vs ${p.ivd}` };
      });
      expect(worst.error, worst.label).toBeLessThan(RELATIVE);
    });
  }
});
